#!/usr/bin/env python3
"""Deploy the pinned morning-market frontend with baseline checks and backups."""
import argparse, base64, hashlib, json, os, subprocess, urllib.request, zlib
from pathlib import Path

MANIFEST = json.loads(zlib.decompress(base64.b64decode('')))
STATE = Path('/home/admin/village-autonomous/files/morning-market-terrain-20261102-v1')

def digest(data):
    return hashlib.sha256(data).hexdigest()

def docker(*args):
    return subprocess.check_output(['sudo', '-n', 'docker', *args], text=True)

def atomic(path, data, mode=0o644):
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + '.market-pending')
    with temp.open('xb') as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())
    temp.chmod(mode)
    os.replace(temp, path)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--apply', action='store_true')
    args = parser.parse_args()
    web = json.loads(docker('inspect', 'village-autonomous-web'))[0]
    mounts = [m for m in web['Mounts'] if m['Destination'] == '/srv/village-web']
    assert len(mounts) == 1 and mounts[0]['RW'] is False, 'UNEXPECTED_MOUNT'
    root = Path(mounts[0]['Source']).resolve()
    assert root.is_relative_to(Path('/home/admin/village-autonomous/files')), 'UNEXPECTED_ROOT'
    before, after = {}, {}
    for name, spec in MANIFEST.items():
        p = root / name
        assert p.resolve().is_relative_to(root) and not p.is_symlink(), 'INVALID_PATH'
        before[name] = p.read_bytes() if p.exists() else None
        current = digest(before[name]) if before[name] is not None else None
        assert current in (spec['before'], spec['after']), 'LIVE_CHANGED:' + name
        after[name] = base64.b64decode(spec['data'])
        assert digest(after[name]) == spec['after'], 'INVALID_PAYLOAD:' + name
    if not args.apply:
        print(json.dumps({'status': 'preflight_passed', 'files': len(after), 'root': str(root)}))
        return
    os.umask(0o077)
    STATE.mkdir(parents=True, exist_ok=True)
    receipt = STATE / 'receipt.json'
    if receipt.exists():
        assert all((root/n).read_bytes() == after[n] for n in after), 'DEPLOYED_CHANGED'
        print(json.dumps({'status': 'already_deployed'}))
        return
    changed = []
    try:
        metadata = {n: {'existed': v is not None, 'sha256': digest(v) if v is not None else None} for n,v in before.items()}
        for name, data in before.items():
            backup = STATE / 'backup' / name
            if data is not None:
                if backup.exists():
                    assert backup.read_bytes() == data, 'BACKUP_CHANGED'
                else:
                    atomic(backup, data, 0o600)
        atomic(STATE / 'before.json', json.dumps(metadata, indent=2).encode(), 0o600)
        # All dependencies and GLBs first; public entry pages last.
        for name in sorted(after, key=lambda n: (n.endswith('index.html'), n)):
            p = root / name
            assert (p.read_bytes() if p.exists() else None) == before[name], 'CONCURRENT_CHANGE:' + name
            if before[name] != after[name]:
                atomic(p, after[name])
                changed.append(name)
        assert json.loads(docker('inspect', 'village-autonomous-web'))[0]['Id'] == web['Id'], 'CONTAINER_CHANGED'
        for name, data in after.items():
            assert (root/name).read_bytes() == data, 'FILE_MISMATCH:' + name
            with urllib.request.urlopen('https://8.148.248.237/'+name+'?release=20261102-market1', timeout=30) as response:
                assert response.read() == data, 'HTTPS_MISMATCH:' + name
        atomic(receipt, json.dumps({'status': 'complete', 'web_root': str(root), 'web_container': web['Id'], 'files': {n:digest(v) for n,v in after.items()}, 'service_restarts': 0}, indent=2).encode(), 0o600)
        print(json.dumps({'status': 'deployed', 'files': len(after), 'service_restarts': 0, 'backup': str(STATE)}))
    except Exception:
        for name in reversed(changed):
            p = root / name
            if p.read_bytes() == after[name]:
                if before[name] is None:
                    p.unlink()
                else:
                    atomic(p, before[name])
        raise

if __name__ == '__main__':
    main()
